module sdp_requant (...);
  // FIFO
  logic [127:0] data0, data1;
  logic [1:0] count; // 0,1,2
  logic in_ready_r;
  assign in_ready = in_ready_r;
  assign out_valid = (count != 0);
  assign out_data = data0;

  // Combinational new word
  logic [127:0] new_word;
  // Functions and always_comb compute new_word from in_data and cfg.
  always_comb begin
    new_word = 128'd0;
    for (int lane=0; lane<4; lane++) begin
      logic signed [15:0] x;
      logic [31:0] lane_out;
      x = in_data[16*lane +: 16]; // Need signed cast
      if (cfg_precision == 2'd2) begin
        lane_out = fp16_to_fp32(in_data[16*lane +: 16], cfg_nan_to_zero);
      end else begin
        if (cfg_bypass) begin
          lane_out = {{16{in_data[16*lane+15]}}, in_data[16*lane +: 16]};
        end else begin
          lane_out = int_requant(x, cfg_offset, cfg_scale, cfg_truncate);
        end
      end
      new_word[32*lane +: 32] = lane_out;
    end
  end

