    function automatic logic [31:0] fp16_to_fp32 (
        input logic [15:0] h,
        input logic        nan_to_zero
    );
        logic        s;
        logic [4:0]  exp16;
        logic [9:0]  frac16;
        logic [7:0]  exp32;
        logic [22:0] mant32;
        logic [31:0] res;
        logic [4:0]  k;
        logic [31:0] shifted;
        integer      i;
        begin
            s = h[15];
            exp16 = h[14:10];
            frac16 = h[9:0];
            if (exp16 == 5'd0) begin
                if (frac16 == 10'd0) begin
                    res = {s, 31'd0};
                end else begin
                    k = 5'd0;
                    for (i = 0; i < 10; i = i + 1) begin
                        if (frac16[i]) begin
                            k = i[4:0];
                        end
                    end
                    exp32 = 8'd103 + {3'b000, k};
                    shifted = {22'd0, frac16} << (23 - k);
                    mant32 = shifted[22:0];
                    res = {s, exp32, mant32};
                end
            end else if (exp16 == 5'd31) begin
                if (frac16 == 10'd0) begin
                    res = s ? 32'hFF7FFFFF : 32'h7F7FFFFF;
                end else begin
                    if (nan_to_zero) begin
                        res = 32'h00000000;
                    end else begin
                        res = {s, 8'hFF, 13'b0, frac16};
                    end
                end
            end else begin
                exp32 = 8'd112 + {3'b000, exp16};
                mant32 = {frac16, 13'b0};
                res = {s, exp32, mant32};
            end
            fp16_to_fp32 = res;
        end
    endfunction

